function context(){renderNavigation();renderDecision();$('#active-project-label').textContent=p().name+' / '+(current()?.name??'ยังไม่มีโครงการลูกค้า');$('#context-project').textContent=current()?.name??'ยังไม่มีโครงการ';$('#context-title').textContent=p().name;$('#context-icon').textContent=p().icon;$('#edit-project').disabled=!current();$('#export').disabled=!current();$('#reset').disabled=!current();if(!current()){$('#context-assumptions').innerHTML='<h3>พร้อมเริ่มโครงการใหม่</h3><p>เพิ่มลูกค้าเพื่อกำหนดสมมติฐานของคุณ</p>';$('#context-recovery').innerHTML='';return;}const result=r(),s=data[selected];$('#context-title').textContent=p().name;$('#context-icon').textContent=p().icon;document.querySelectorAll('[data-solution]').forEach(b=>{b.classList.toggle('active',b.dataset.solution===selected);b.setAttribute('aria-pressed',String(b.dataset.solution===selected))});$('#context-assumptions').innerHTML=`<h3>สมมติฐานโครงการ <button class="text-button" data-go-inputs>แก้ไข ↗</button></h3><div class="context-row"><span>เงินลงทุนเริ่มต้น</span><b>${fmt(s.initial_investment/1e6,2)} ล้านบาท</b></div><div class="context-row"><span>อายุโครงการ</span><b>${s.project_life} ปี</b></div><div class="context-row"><span>อัตราคิดลด</span><b>${fmt(s.discount_rate*100,1)}%</b></div><div class="context-row"><span>รายได้ปีแรก</span><b>${fmt(s.revenue_y1/1e6,2)} ล้านบาท</b></div>`;$('#context-recovery').innerHTML=`<h3>จุดคืนทุน <span class="chip">BREAK-EVEN</span></h3><div class="recovery-item"><small>แบบปกติ</small><strong>${yrs(result.payback)}${result.payback==null?'':'<em>ปี</em>'}</strong></div><div class="recovery-item mint"><small>แบบคิดลด · ${fmt(s.discount_rate*100,1)}%</small><strong>${yrs(result.discounted_payback)}${result.discounted_payback==null?'':'<em>ปี</em>'}</strong></div><p style="font-size:9px;line-height:1.9">ประมาณปีแรกที่กระแสเงินสดสะสมแตะศูนย์${result.break_even.simpleFallsBelowAgain||result.break_even.discountedFallsBelowAgain?' · บางปีหลังคืนทุนกลับมาติดลบ โปรดดูค่าเปลี่ยนอุปกรณ์':''}</p>`;$('#context-assumptions [data-go-inputs]').onclick=()=>navigate('inputs');}
function metricCards(result){const cs=customerSavings(result,selected),saving=cs.savingExVat??cs.saving,why=cs.kind==='shift'?'จาก peak shaving':cs.kind==='ppa'?'PPA ถูกกว่าไฟกริด':selected==='solar'?'จากส่วนลดค่าไฟ PPA':selected==='battery'?'จากส่วนแบ่งผลประหยัดแบต':'จากส่วนลด PPA + ส่วนแบ่งผลประหยัดแบต',foot=cs.kind==='bill'?'ก่อน VAT · ตรงกับ Excel (กราฟผลประหยัดแสดงแบบรวม VAT)':cs.source,hurdle=result.scenario.discount_rate,irr=result.irr,lcoe=result.lcoe,spread=irr==null?null:(irr-hurdle)*100;return `<div class="metric-grid"><article class="card metric-card"><div class="metric-label">มูลค่าปัจจุบันสุทธิ <span>NPV ↗</span></div><div class="metric-value">${fmt(result.npv/1e6,2)}<em>ล้านบาท</em></div><div class="metric-note ${result.npv>=0?'positive':'negative'}">${result.npv>=0?'มูลค่าสุทธิสูงกว่าเงินลงทุน':'มูลค่าสุทธิต่ำกว่าเงินลงทุน'}</div><div class="metric-footer"><span>คิดลดที่ ${fmt(hurdle*100,1)}%</span><span>${result.scenario.project_life} ปี</span></div></article><article class="card metric-card"><div class="metric-label">อัตราผลตอบแทน <span>IRR</span></div><div class="metric-value">${irr==null?'—':fmt(irr*100,2)}<em>%</em></div><div class="metric-note ${spread!=null&&spread>0?'positive':'negative'}">${spread==null?'คำนวณ IRR ไม่ได้':`${spread>=0?'+':''}${fmt(spread,2)} จุดเปอร์เซ็นต์ เทียบเกณฑ์`}</div><div class="irr-compare"><i style="height:${Math.max(2,Math.min(30,(irr??0)*120))}px" title="IRR ${irr==null?'คำนวณไม่ได้':fmt(irr*100,2)+'%'}"></i><i style="height:${Math.max(2,Math.min(30,hurdle*120))}px" title="เกณฑ์ ${fmt(hurdle*100,2)}%"></i><span style="font-size:8px;color:#8fa8bf;margin:0 0 3px 3px">IRR / เกณฑ์</span></div></article><article class="card metric-card"><div class="metric-label">จุดคุ้มทุน <span>Break-even</span></div><div class="metric-value">${result.payback==null?'—':fmt(result.payback,2)}<em>${result.payback==null?'ไม่คืนทุนในอายุโครงการ':'ปี'}</em></div><div class="metric-note">คิดลด ${result.discounted_payback==null?'ไม่คืนทุนในอายุโครงการ':fmt(result.discounted_payback,2)+' ปี'}</div><div class="metric-footer"><span>จากกระแสเงินสดสะสม</span></div></article><article class="card metric-card"><div class="metric-label">ต้นทุนพลังงานเฉลี่ย <span>LCOE</span></div><div class="metric-value">${lcoe==null?'—':fmt(lcoe,2)}<em>บาท/kWh</em></div><div class="metric-note">PV ต้นทุน / PV พลังงาน${result.lcoe_degradation>0?` · ไฟลดปีละ ${fmt(result.lcoe_degradation*100,1)}% ตามการเสื่อม`:''}</div><div class="metric-footer"><span>ตามสมมติฐานของตัวอย่าง</span></div></article><article class="card metric-card"><div class="metric-label">ประหยัดฝั่งลูกค้า / ปี <span>SAVING</span></div>${saving>0?`<div class="metric-value">${fmt(saving)}<em>บาท</em></div><div class="metric-note positive">▲ ${why}</div><div class="metric-footer"><span>${foot}</span></div>`:`<div class="metric-value">—</div><div class="metric-note">${cs.kind==='ppa'?'ราคา PPA ไม่ต่ำกว่าค่าไฟกริด':'ไม่มีผลประหยัด'}</div><div class="metric-footer"><span>${cs.source}</span></div>`}</article>${result.equity?`<article class="card metric-card"><div class="metric-label">ส่วนทุน (มีเงินกู้) <span>EQUITY</span></div><div class="metric-value">${result.equity.irr==null?'—':fmt(result.equity.irr*100,2)}<em>% IRR</em></div><div class="metric-note ${result.equity.npv>=0?'positive':'negative'}">NPV ส่วนทุน ${fmt(result.equity.npv/1e6,2)} ล้านบาท</div><div class="metric-footer"><span>กู้ ${fmt(result.equity.debt/1e6,2)} ล้านบาท · งวดละ ${fmt(result.equity.payment)} บาท</span></div></article>`:''}</div><p class="tax-note">NPV · IRR · คืนทุน · ผลประหยัด: <b>${taxNote([result.scenario])}</b></p>`;}
const chartTitles={cumulative:'กระแสเงินสดและจุดคืนทุน',annual:'กระแสเงินสดสุทธิรายปี',savings:'ผลประหยัดค่าไฟ',sensitivity:'ความอ่อนไหวของ NPV',costs:'องค์ประกอบต้นทุน',npv:'เปรียบเทียบ NPV',irr:'เปรียบเทียบ IRR',recovery:'เปรียบเทียบจุดคืนทุน'};
const chartDescriptions={cumulative:'สองมุมมองของการคืนทุน · หน่วย: ล้านบาท',annual:'กระแสเงินสดปีที่ 1 เป็นต้นไป · ไม่รวมเงินลงทุนปี 0',savings:'ส่วนต่างค่าไฟ Peak / Off-peak',sensitivity:'เปลี่ยนทีละตัวแปร โดยคงสมมติฐานอื่น',costs:'ต้นทุนรวมตลอดอายุโครงการ · ไม่คิดลด',npv:'มูลค่าปัจจุบันสุทธิ · ล้านบาท',irr:'เทียบอัตราผลตอบแทน · %',recovery:'จุดคืนทุนปกติและคิดลด · ปี'};
function allResults(){return products.filter(pr=>activeProject(state,pr.id)).map(pr=>({...pr,projectName:activeProject(state,pr.id).name,result:computeScenario(data[pr.id])}));}
// NPV sensitivity: raw-input projects vary each real input over its own range (Khun Ton: documented ranges; others: ±range); direct-input projects vary the model fields ±range
const SENS_SHORT={useman:'สัดส่วนไฟที่ใช้ได้',cost:'ต้นทุนติดตั้งโซลาร์',yld:'ไฟที่ผลิตได้ต่อ kWp',om:'O&M โซลาร์',deg:'แผงเสื่อมต่อปี',disc:'ส่วนลด PPA',esc:'ค่าไฟขึ้นต่อปี',ft:'ค่า Ft',invC:'ค่าเปลี่ยนอินเวอร์เตอร์',bpack:'ราคาแบต',rte:'ประสิทธิภาพแบต',relT:'Demand ที่แบตลดได้',bdeg:'แบตเสื่อมต่อปี',bom:'O&M แบต',share:'ส่วนแบ่งของ กฟผ.',bsalv:'มูลค่าซากแบต',rate:'อัตราคิดลด'};
let sensMemo={key:null,val:null};
function sensModel(){const s=data[selected];if(s?.input_mode!=='raw'||!rawComplete(selected,s))return null;const raw={sel:{...defaultRaw().sel,...(s.raw?.sel??{})},values:{...(s.raw?.values??{})}},sample=isSample(s),key=selected+JSON.stringify(raw)+sample+(sample?'':range);if(sensMemo.key!==key){const res=sensRaw(selected,raw,sample,['rate'],range);sensMemo={key,val:res&&res.rows.length?{...res,sample}:null};}return sensMemo.val;}
const sensVal=(x,u)=>u==='%'?(+(x*100).toFixed(2)).toLocaleString('en-US')+'%':(+x.toFixed(Math.abs(x)>=100?0:4)).toLocaleString('en-US',{maximumFractionDigits:4})+(u?' '+u:'');
function sensItems(m){const base=m.base.npv;return [...m.rows].sort((a,b)=>Math.abs(b.H.npv-b.L.npv)-Math.abs(a.H.npv-a.L.npv)).map(o=>({name:SENS_SHORT[o.key]??o.label,o,low:(o.L.npv-base)/1e6,high:(o.H.npv-base)/1e6,tipLow:o.label+' '+sensVal(o.lo,o.unit),tipHigh:o.label+' '+sensVal(o.hi,o.unit)}));}
const signed=v=>(v>0?'+':v<0?'−':'')+fmt(Math.abs(v),2);
function chartBody(id,height,width){const result=r();if(id==='cumulative')return cumulative(result,lineVisible,height,width);if(id==='annual')return annual(result,height,width,annualYears);if(id==='savings')return savings(result,saveMode,selected,height,width);if(id==='sensitivity'){const m=sensModel();return m?sensitivity(result,range,height,width,{items:sensItems(m),label:'ผลกระทบต่อ NPV เมื่อเปลี่ยนค่าที่ใส่ทีละตัวตามช่วงที่เป็นไปได้'}):sensitivity(result,range,height,width);}if(id==='costs')return costs(result,height,width,costFocus);return comparison(allResults(),id,height,width);}
function chartLegend(id){if(id==='savings'&&saveMode==='cumulative')return `<div class="legend"><span><i class="dash" style="background:none;border-top:2px dashed var(--orange)"></i>ไม่ติดตั้ง</span><span><i class="mint"></i>ติดตั้ง ${p().name}</span><span><i class="gap-swatch"></i>ส่วนที่ประหยัด</span></div>`;if(id==='cumulative')return `<div class="legend"><button data-line="simple" aria-pressed="${lineVisible.simple}"><i></i>สะสมปกติ</button><button data-line="discount" aria-pressed="${lineVisible.discount}"><i class="dash"></i>สะสมคิดลด</button></div>`;if(id==='sensitivity'){const m=sensModel();if(m){const it=sensItems(m)[0],o=it.o,u=o.unit,lo=sensVal(o.lo,u),hi=sensVal(o.hi,u);return `<div class="legend"><span><i></i>ใช้ค่าต่ำสุดของช่วง</span><span><i class="mint"></i>ใช้ค่าสูงสุดของช่วง</span></div><p class="legend-note"><b>ค่าต่ำสุด / ค่าสูงสุดของช่วง</b> = ค่าที่น้อยที่สุดและมากที่สุดที่เป็นไปได้ของค่านั้น ตามข้อมูลจริงหรืองานวิจัย · แต่ละแท่งบอกว่าถ้าค่านั้นเป็นค่าต่ำสุดหรือสูงสุด (ค่าอื่นคงเดิม) NPV จะเปลี่ยนจากค่าฐานเท่าไร: แท่งไปทางขวา = NPV สูงขึ้น · ไปทางซ้าย = NPV ลดลง · แท่งยาว = ค่านั้นมีผลมาก · ค่าต่ำสุดไม่ได้แปลว่าแย่เสมอ เช่น ${esc(o.label)} ${lo} ทำให้ NPV ${it.low>=0?'สูงขึ้น':'ลดลง'} ${fmt(Math.abs(it.low),2)} ล้านบาท ส่วน ${hi} ทำให้ NPV ${it.high>=0?'สูงขึ้น':'ลดลง'} ${fmt(Math.abs(it.high),2)} ล้านบาท</p>`;}}if(id==='sensitivity')return `<div class="legend"><span><i></i>สมมติฐาน −${range*100}%</span><span><i class="mint"></i>สมมติฐาน +${range*100}%</span></div>`;if(id==='recovery')return '<div class="legend"><span><i></i>ปกติ</span><span><i class="mint"></i>คิดลด</span></div>';if(id==='annual')return '<div class="legend"><span><i class="blue"></i>กระแสเงินสดบวก</span><span><i></i>กระแสเงินสดลบ</span></div>';return '';}
// Every result says whether tax is in it (the model takes income tax only when tax_rate > 0; prices never include VAT)
const taxNote=list=>{const t=list.filter(s=>(s?.tax_rate??0)>0);return !t.length?'ตัวเลขยังไม่รวมภาษี':t.length===list.length&&new Set(t.map(s=>s.tax_rate)).size===1?`รวมภาษีเงินได้ ${fmt(t[0].tax_rate*100,0)}% แล้ว · ยังไม่รวม VAT`:'บางโครงการรวมภาษีเงินได้แล้ว · ยังไม่รวม VAT';};
function chartNote(id){if(id==='savings'&&isSample(data[selected]))return chartNoteBase(id)+' · <b class="tax-tag">กราฟนี้รวม VAT 7% ตามบิลจริง · ยังไม่รวมภาษีเงินได้</b>';const tax=['npv','irr','recovery'].includes(id)?taxNote(allResults().map(x=>x.result.scenario)):taxNote([data[selected]]);return chartNoteBase(id)+` · <b class="tax-tag">${tax}</b>`;}
function chartNoteBase(id){if(id==='cumulative')return `เส้นทึบ = เงินสดสะสมตามจริง · เส้นประ = คิดเป็นมูลค่าวันนี้ที่อัตราคิดลด ${fmt((data[selected]?.discount_rate??0)*100,1)}% ปลายเส้นประจึงเท่ากับ NPV · จุดบนเส้นศูนย์ = ปีที่คืนทุนครั้งแรก (คิดเศษปีแบบเส้นตรง) · รวมมูลค่าซาก`;if(id==='savings')return isSample(data[selected])?`ไม่ติดตั้ง = ค่าไฟจริง 6 เดือน (${currentBill().from} – ${currentBill().to}) ${fmt(currentBill().half,2)} บาท × 2 = ${fmt(currentBill().year)} บาทในปีแรก แล้วขึ้นตามค่าไฟปีละ ${fmt((data[selected].raw?.values?.esc??0)*100,1)}% โดยใช้ไฟเท่าเดิม · ติดตั้ง = ค่าไฟเดิม − ผลประหยัดจากกระแสเงินสดชุดเดียวกับกราฟอื่น (รวมการเสื่อมและการเปลี่ยนแบตแล้ว) คูณ VAT 7% ให้เทียบกับบิลได้`:data[selected]?.input_mode==='raw'?'คิดจากกระแสเงินสดชุดเดียวกับกราฟอื่น · รวมค่าไฟขึ้น การเสื่อม และการเปลี่ยนแบตแล้ว · ผลประหยัดแบตรวมค่า Demand และหักค่าไฟชาร์จแล้ว':selected==='solar'?'สมมติไฟโซลาร์ใช้แทนไฟกริดช่วง Peak · ราคา PPA = รายได้ปีแรก ÷ พลังงานปีแรก · ไม่รวม demand charge และภาษี':'แบบจำลองส่วนต่างค่าไฟ ไม่รวมประสิทธิภาพแบตเตอรี่ การเสื่อม และ demand charge';if(id==='sensitivity'){const m=sensModel();return m?`เส้นกลาง = NPV ค่าฐาน ${signed(m.base.npv/1e6)} ล้านบาท · ${m.sample?'ช่วงของแต่ละค่ามาจากข้อมูลจริงและงานวิจัยของคุณต้น':'ช่วง ±'+range*100+'% จากค่าที่ใส่'} · กดแถวเพื่อดูที่มา IRR และน้ำหนัก`:`เส้นกลาง = ΔNPV 0 · เปรียบเทียบกับฐาน ${fmt(r().npv/1e6,2)} ล้านบาท`;}if(id==='costs')return 'บวกเงินทุกก้อนที่จ่ายตลอดโครงการตามจริง ไม่คิดลด (เงินปีที่ 0 กับเงินปีอนาคตนับเท่ากัน) · ใช้ดูว่าเงินไปอยู่ส่วนไหน ไม่ได้ใช้วัดความคุ้ม ความคุ้มดูที่ NPV · ไม่หักมูลค่าซาก';if(['npv','irr','recovery'].includes(id))return 'โครงการตัวอย่างมีขนาดและอายุต่างกัน ไม่ใช่การจัดอันดับผลิตภัณฑ์';return 'แต่ละแท่ง = เงินเข้า − เงินออกของปีนั้น ไม่รวมเงินลงทุนปี 0 · แท่งที่ลดลงมาก = ปีที่เปลี่ยนอุปกรณ์ · แท่งสุดท้ายรวมมูลค่าซาก · วางเมาส์บนแท่งเพื่อดูยอดรายปี';}
function controls(id){if(id==='savings')return `<div class="chart-control"><button data-saving="annual" class="${saveMode==='annual'?'active':''}">รายปี</button><button data-saving="cumulative" class="${saveMode==='cumulative'?'active':''}">สะสม</button></div>`;if(id==='annual')return `<div class="chart-control">${[[5,'5 ปี'],[10,'10 ปี'],[null,'ทั้งโครงการ']].map(([v,l])=>`<button data-years="${v??'all'}" class="${annualYears===v?'active':''}" aria-pressed="${annualYears===v}">${l}</button>`).join('')}</div>`;if(id==='sensitivity'&&sensModel()?.sample)return '';if(id==='sensitivity')return `<div class="chart-control">${[.1,.2,.3].map(v=>`<button data-range="${v}" class="${v===range?'active':''}">±${v*100}%</button>`).join('')}</div>`;return '';}
function costDetail(result){const s=result.scenario,rows=result.cashflows,sum=k=>rows.reduce((a,v)=>a+v[k],0),items=[['เงินลงทุน',s.initial_investment,[['จ่ายครั้งเดียว','ปี 0'],['ต่อปีของอายุโครงการ',fmt(s.initial_investment/s.project_life)+' บาท']]],['ค่า O&M',sum('om_cost'),[['ปีแรก',fmt(s.om_y1)+' บาท'],['เติบโต',fmt((s.om_growth??0)*100,1)+'% ต่อปี'],['ปีสุดท้าย',fmt(rows.at(-1).om_cost)+' บาท']]],['ค่าใช้จ่ายอื่น',sum('other_cost'),[['ปีแรก',fmt(s.other_y1)+' บาท'],['เติบโต',fmt((s.other_growth??0)*100,1)+'% ต่อปี'],['ปีสุดท้าย',fmt(rows.at(-1).other_cost)+' บาท']]],['เปลี่ยนอุปกรณ์',sum('replacement'),sum('replacement')>0?[...(s.replacement_year?[['รายการที่ 1','ปี '+s.replacement_year+' · '+fmt(s.replacement_cost)+' บาท']]:[]),...(sum('replacement2')>0?[['รายการที่ 2',(s.replacement2_every?'ทุก '+s.replacement2_every+' ปี':'ปี '+s.replacement2_year)+' · '+fmt(s.replacement2_cost)+' บาท/ครั้ง']]:[])]:[['ตามสมมติฐาน','ไม่มีการเปลี่ยนอุปกรณ์']]],...(sum('tax')>0?[['ภาษี',sum('tax'),[['อัตรา',fmt((s.tax_rate??0)*100,1)+'%'],['ค่าเสื่อม',fmt(s.initial_investment/(s.depreciation_years||s.project_life))+' บาท/ปี']]]]:[])],total=items.reduce((a,v)=>a+v[1],0);if(costFocus==null)return `<p class="cost-hint">กดที่วงกลมหรือรายการ เพื่อดูรายละเอียดแต่ละต้นทุน</p>`;const [name,v,facts]=items[costFocus];return `<div class="cost-detail"><div class="cost-detail-head"><b>${name}</b><button data-cost-close aria-label="ปิดรายละเอียด">×</button></div><div class="cost-detail-total">${fmt(v)} <small>บาท · ${fmt(total?v/total*100:0,1)}% ของต้นทุนทั้งหมด</small></div><dl>${facts.map(([k,val])=>`<div><dt>${k}</dt><dd>${val}</dd></div>`).join('')}</dl></div>`;}
// Click any point, bar or row to see its numbers (same idea as the cost breakdown).
const PICKABLE=new Set(['cumulative','annual','savings','sensitivity','npv','recovery','irr']);
const pickHints={cumulative:'กดที่ปีใดก็ได้บนกราฟ เพื่อดูยอดสะสมของปีนั้น',annual:'กดที่แท่งของปีใดก็ได้ เพื่อดูรายได้และค่าใช้จ่ายของปีนั้น',savings:'กดที่แท่งหรือปี เพื่อดูรายละเอียดค่าไฟ',sensitivity:'กดที่แถว เพื่อดูช่วงที่ทดสอบ ที่มา NPV และ IRR',npv:'กดที่ผลิตภัณฑ์ เพื่อดูตัวเลขของโครงการ',recovery:'กดที่ผลิตภัณฑ์ เพื่อดูตัวเลขของโครงการ',irr:'กดที่ผลิตภัณฑ์ เพื่อดูตัวเลขของโครงการ'};
const yrsTxt=v=>v==null?'ไม่คืนทุนในอายุโครงการ':fmt(v,2)+' ปี';
function whyNote(rows,row){const w=explainYear(row,rows.find(x=>x.year===row.year-1)??null);if(!w.text&&!w.cumulativeDips)return '';return `<div class="why ${w.negative?'neg':''}"><b>${w.negative?'ทำไมกระแสเงินสดปีนี้ติดลบ':'หมายเหตุปีนี้'}</b>${w.text?`<p>${w.text}</p>`:''}${w.cumulativeDips&&row.cumulative>=0?`<p>ยอดสะสมลดลงจากปีก่อน แต่ยังเป็นบวก จึงยังถือว่าคืนทุนแล้ว</p>`:''}<code>${w.formula}</code><small>ตัวเลขแต่ละช่องปัดเป็นบาท ผลรวมที่ปัดแล้วอาจต่างกัน 1 บาท</small></div>`;}
function pickData(id){const v=picks[id];if(v==null)return null;const result=r(),baht=x=>fmt(x)+' บาท';
 if(id==='cumulative'){const row=result.cashflows.find(c=>c.year===v);if(!row)return null;return {title:'ปีที่ '+v,total:fmt(row.cumulative),unit:'บาท · กระแสเงินสดสะสมปกติ',facts:[['สะสมคิดลด',baht(row.discounted_cumulative)],['กระแสเงินสดสุทธิปีนี้',baht(row.net_cf)],['มูลค่าปัจจุบันปีนี้',baht(row.present_value)],['สถานะ',row.cumulative>=0?'คืนทุนแล้ว':'ยังไม่คืนทุน']],note:whyNote(result.cashflows,row)};}
 if(id==='annual'){const row=result.cashflows.find(c=>c.year===v&&c.year>0);if(!row||(annualYears&&v>annualYears))return null;return {title:'ปีที่ '+v,total:fmt(row.net_cf),unit:'บาท · กระแสเงินสดสุทธิ',neg:row.net_cf<0,facts:[['รายได้ / ผลประหยัด',baht(row.revenue)],['ค่า O&M',baht(row.om_cost)],['ค่าใช้จ่ายอื่น',baht(row.other_cost)],['เปลี่ยนอุปกรณ์',baht(row.replacement)],['มูลค่าซาก',baht(row.salvage)]],note:whyNote(result.cashflows,row)};}
 if(id==='savings'){const c=customerSavings(result,selected);if(saveMode==='cumulative'){const row=c.cumulative.find(x=>x.year===v);if(!row)return null;return {title:'ค่าไฟสะสม '+v+' ปี',total:fmt(row.cumulative),unit:'บาท · ประหยัดสะสม',facts:[...(row.bill!=null?[['ค่าไฟปีที่ '+v+' (ไม่ติดตั้ง)',baht(row.bill)],['อัตราค่าไฟขึ้น','ปีละ '+fmt(c.growth*100,1)+'%'],...(v>1?[['ค่าไฟปีที่ '+v+' เทียบปีแรก',(row.bill>=c.before?'+':'')+fmt((row.bill/c.before-1)*100,2)+'%']]:[]),['ประหยัดปีที่ '+v,baht(row.saving)]]:[]),['ถ้าไม่ติดตั้ง',baht(row.before)],['หลังติดตั้ง',baht(row.after)],['ประหยัดได้',fmt(row.before?row.cumulative/row.before*100:0,1)+'% ของค่าไฟ'],['ประหยัดต่อปี',baht(row.saving)]].filter(f=>row.bill==null||f[0]!=='ประหยัดต่อปี')};}
  if(v!==0&&v!==1)return null;return {title:v?c.afterTitle:c.beforeTitle,total:fmt(v?c.after:c.before),unit:'บาท / ปี',facts:v?c.factsAfter:c.factsBefore};}
 if(id==='sensitivity'){const m=sensModel();if(m){const it=sensItems(m)[v];if(!it)return null;const o=it.o,u=o.unit,be=m.top.find(t=>t.key===o.key),swing=Math.abs(o.H.npv-o.L.npv)/1e6;return {title:o.label,total:fmt(swing,2),unit:'ล้านบาท · ช่วงที่ NPV เปลี่ยน',facts:[['ช่วงที่ทดสอบ',sensVal(o.lo,u==='%'?u:'')+' – '+sensVal(o.hi,u)],['NPV เมื่อใช้ค่าต่ำสุด',signed(o.L.npv/1e6)+' ล้านบาท'],['NPV เมื่อใช้ค่าสูงสุด',signed(o.H.npv/1e6)+' ล้านบาท'],['IRR เมื่อใช้ค่าต่ำสุด',fmt(o.L.irr*100,2)+'%'],['IRR เมื่อใช้ค่าสูงสุด',fmt(o.H.irr*100,2)+'%'],...(o.policy?[['น้ำหนัก','ไม่นับ · เป็นเกณฑ์ที่ กฟผ. กำหนด']]:[['น้ำหนักต่อ NPV',fmt(o.wNpv*100,1)+'%'],['น้ำหนักต่อ IRR',fmt(o.wIrr*100,1)+'%']]),...(be&&be.breakEven!=null?[['IRR ถึงเกณฑ์ '+fmt(m.hurdle*100,0)+'% เมื่อค่านี้เป็น',(u==='%'?fmt(be.breakEven*100,1)+'%':fmt(be.breakEven,be.breakEven>=100?0:1)+' '+u)]]:[])],note:`<div class="why"><b>ที่มาของช่วง</b><p>${esc(o.src)}</p><p>${o.policy?'อัตราคิดลดไม่เปลี่ยน IRR และเป็นเกณฑ์ที่ กฟผ. กำหนด ไม่ใช่ข้อมูลที่คลาดเคลื่อน จึงไม่นับในน้ำหนัก':`น้ำหนัก = (ช่วงที่แกว่ง)² ÷ ผลรวมของทุกปัจจัย · ปัจจัยนี้ทำให้ NPV แกว่ง ${fmt(swing,2)} ล้านบาท`}</p></div>`};}const it=sensitivityItems(result,range)[v];if(!it)return null;return {title:it.name+' ±'+range*100+'%',total:fmt(Math.abs(it.high-it.low),2),unit:'ล้านบาท · ช่วงที่ NPV เปลี่ยน',facts:[['NPV ฐาน',fmt(result.npv/1e6,2)+' ล้านบาท'],['เมื่อ −'+range*100+'%',fmt((result.npv/1e6)+it.low,2)+' ล้านบาท ('+(it.low>=0?'+':'')+fmt(it.low,2)+')'],['เมื่อ +'+range*100+'%',fmt((result.npv/1e6)+it.high,2)+' ล้านบาท ('+(it.high>=0?'+':'')+fmt(it.high,2)+')']]};}
 const pr=allResults()[v];if(!pr)return null;const x=pr.result;return {title:pr.name+' · '+esc(pr.projectName),total:id==='irr'?(x.irr==null?'—':fmt(x.irr*100,2)):id==='recovery'?yrsTxt(x.payback).replace(' ปี',''):fmt(x.npv/1e6,2),unit:id==='irr'?'% · IRR':id==='recovery'?(x.payback==null?'':'ปี · คืนทุนปกติ'):'ล้านบาท · NPV',facts:[['เงินลงทุน',fmt(x.scenario.initial_investment/1e6,2)+' ล้านบาท'],['NPV',fmt(x.npv/1e6,2)+' ล้านบาท'],['IRR',x.irr==null?'—':fmt(x.irr*100,2)+'%'],['คืนทุนปกติ',yrsTxt(x.payback)],['คืนทุนคิดลด',yrsTxt(x.discounted_payback)],['การตัดสินใจ',x.decisionFinal.toUpperCase()]]};}
function pickDetail(id){const d=pickData(id);if(!d)return `<div class="pick-slot"><p class="cost-hint">${pickHints[id]}</p></div>`;return `<div class="pick-slot"><div class="cost-detail pick-detail"><div class="cost-detail-head"><b>${d.title}</b><button data-pick-close aria-label="ปิดรายละเอียด">×</button></div><div class="cost-detail-total ${d.neg?'neg':''}" data-count>${d.total} <small>${d.unit}</small></div><dl>${d.facts.map(([k,val])=>`<div><dt>${k}</dt><dd>${val}</dd></div>`).join('')}</dl>${d.note||''}</div></div>`;}
function applyPick(host,id){const v=picks[id],svgEl=host.querySelector('svg');if(!svgEl)return;svgEl.classList.toggle('has-pick',v!=null);host.querySelectorAll('[data-pick]').forEach(el=>el.classList.toggle('picked',v!=null&&el.dataset.pick===String(v)));}
function setPick(card,id,v){picks[id]=v;const slot=card.querySelector('.pick-slot');if(slot){slot.outerHTML=pickDetail(id);countUp(card.querySelector('.pick-slot'));}const host=card.querySelector('[data-fit-chart]');if(host)applyPick(host,id);}
function bindPicks(root){const cards=root.matches?.('[data-chart-card]')?[root]:[...root.querySelectorAll('[data-chart-card]')];cards.forEach(card=>{const id=card.dataset.chartCard;if(!PICKABLE.has(id))return;const host=card.querySelector('[data-fit-chart]');if(!host)return;host.tabIndex=0;host.setAttribute('aria-label',chartTitles[id]+' · กดหรือใช้ลูกศรซ้าย/ขวาเพื่อดูรายละเอียด');card.addEventListener('click',e=>{if(e.target.closest('[data-pick-close]')){setPick(card,id,null);return;}const el=e.target.closest('[data-pick]');if(!el||!host.contains(el))return;const v=Number(el.dataset.pick);setPick(card,id,picks[id]===v?null:v);});host.addEventListener('keydown',e=>{const keys=[...new Set([...host.querySelectorAll('[data-pick]')].map(el=>Number(el.dataset.pick)))].sort((a,b)=>a-b);if(!keys.length)return;const i=keys.indexOf(picks[id]);if(e.key==='ArrowRight'||e.key==='ArrowDown'){e.preventDefault();setPick(card,id,keys[Math.min(keys.length-1,i+1)]);}else if(e.key==='ArrowLeft'||e.key==='ArrowUp'){e.preventDefault();setPick(card,id,keys[Math.max(0,i<0?0:i-1)]);}else if(e.key==='Escape'){setPick(card,id,null);}});});}
function refreshCard(id,animate=true){const old=$(`#content [data-chart-card="${id}"]`);if(!old)return render();const tmp=document.createElement('div');tmp.innerHTML=chartCard(id);const card=tmp.firstElementChild;old.replaceWith(card);bindCharts(card);bindChartSizing(card,animate);}
function chartCard(id){const result=r();let pre='';if(id==='savings'){const cs=customerSavings(result,selected);pre=`<div class="small-label">${saveMode==='annual'?'ผลประหยัดต่อปี':'ผลประหยัดตลอดโครงการ'} · ${cs.source}</div><div class="savings-total" data-count>${fmt(saveMode==='annual'?cs.saving:(cs.cumulative.at(-1)?.cumulative??0))} <em>บาท</em></div>`;}if(id==='sensitivity'){const m=sensModel();if(m)pre=`<div class="cashflow-amount">${signed(m.npvMin/1e6)} ถึง ${signed(m.npvMax/1e6)}<small>ล้านบาท · NPV เมื่อเปลี่ยนค่าทีละตัว · IRR ${fmt(m.irrMin*100,2)}% ถึง ${fmt(m.irrMax*100,2)}%</small></div>`;}if(id==='annual')pre=`<div class="cashflow-amount">${fmt(result.cashflows[1].net_cf/1e6,2)}<small>ล้านบาท · กระแสเงินสดสุทธิปีแรก</small></div>`;const layout=chartLayout(id),hasPlot=true;return `<section class="card chart-card ${layout.wide?'chart-wide':''}" data-chart-card="${id}"><div class="card-head"><div><h3>${chartTitles[id]}</h3><p>${id==='savings'&&isSample(data[selected])?'ค่าไฟทั้งปีของคุณต้นจากบิลจริง เทียบก่อนและหลังติดตั้ง':id==='savings'&&data[selected]?.input_mode==='raw'?'ค่าไฟส่วนที่ระบบช่วยลด เทียบกับเงินที่จ่ายให้ กฟผ.':id==='savings'&&selected==='solar'?'ค่าไฟจากกริดเทียบกับค่าไฟตามสัญญา PPA':id==='sensitivity'&&sensModel()?'เปลี่ยนค่าที่ใส่ทีละตัวตามช่วงที่เป็นไปได้ โดยคงค่าอื่นไว้':chartDescriptions[id]}</p>${controls(id)}</div></div>${hasPlot?`<div class="chart-tools"><button class="chart-toggle" data-size-toggle="${id}" aria-expanded="${layout.wide}" aria-label="${layout.wide?'ย่อ':'ขยาย'}กราฟ ${chartTitles[id]}">${layout.wide?'↙ ย่อกราฟ':'↗ ขยายกราฟ'}</button></div>`:''}${pre}<div class="chart-host ${hasPlot?'resizable-chart':''}" ${hasPlot?`style="height:${layout.wide?chartSize(id).big:chartSize(id).base}px" data-fit-chart="${id}"`:''}>${chartBody(id)}</div>${id==='costs'?costDetail(result):''}${PICKABLE.has(id)&&hasPlot?pickDetail(id):''}${chartLegend(id)}<p class="graph-note">${chartNote(id)}</p></section>`;}
function render(){chartObservers.forEach(o=>o.disconnect());chartObservers=[];if(!current()&&page!=='compare'){$('#content').innerHTML=`<section class="empty-project card"><span>＋</span><h2>สร้างโครงการแรกของ ${p().name}</h2><p>ใช้ปุ่ม “＋ เพิ่มโครงการลูกค้า” ใน sidebar เพื่อเริ่มต้น</p><button class="button" id="show-projects">ดู sidebar โครงการ ←</button></section>`;$('#show-projects').onclick=()=>{if(matchMedia('(max-width:900px)').matches)$('#sidebar-open').click();else $('#project-tree .add-child').focus();};return;}const result=r(),s=data[selected];let html='';
 if(page==='overview'){html=`<section class="card scenario-hero"><div class="scenario-copy"><span class="eyebrow">YOUR ENERGY SCENARIO</span><h2>${p().name} · ${esc(current().name)}</h2><p>${p().desc}</p><div class="scenario-meta"><span>อายุโครงการ <b>${s.project_life} ปี</b></span><span>อัตราคิดลด <b>${fmt(s.discount_rate*100,1)} %</b></span><span>รายได้ / ผลประหยัดปีแรก <b>${fmt(s.revenue_y1)} ฿</b></span></div></div><div class="scenario-invest"><small>เงินลงทุนเริ่มต้น</small><strong>${fmt(s.initial_investment)} ฿</strong><button class="chart-toggle" data-go-inputs>ปรับสมมติฐาน ↗</button></div></section>`+metricCards(result)+`<div class="chart-stack">${chartCard('cumulative')}${chartCard('annual')}${chartCard('sensitivity')}</div><div class="status-strip"><span>✧</span><div>${result.irr==null?'ไม่สามารถสรุปเกณฑ์ IRR ได้':result.irr>s.discount_rate?'IRR สูงกว่าอัตราผลตอบแทนขั้นต่ำที่กำหนด':'IRR ยังไม่สูงกว่าอัตราผลตอบแทนขั้นต่ำที่กำหนด'}</div><small>ผลจากสมมติฐาน · ไม่ใช่การรับประกัน</small></div>`;}
 if(page==='charts')html=`<p class="page-intro">กราฟใหญ่แสดงแถวละหนึ่งกราฟ · กด “ขยายกราฟ” เพื่อดูละเอียดขึ้น</p><div class="chart-stack">${chartCard('cumulative')}${chartCard('annual')}${chartCard('sensitivity')}${chartCard('savings')}${chartCard('costs')}</div>`;
 if(page==='cashflow')html=`<div class="full-chart">${chartCard('annual')}</div><section class="card table-card cashflow-table ${tableOpen?'':'collapsed'}"><div class="card-head"><div><h3>ตารางกระแสเงินสด</h3><p>ปี 0 รวมเงินลงทุนเริ่มต้น · หน่วย: บาท · ${s.project_life+1} แถว · <b class="tax-tag">${taxNote([s])}</b></p></div><div class="table-actions"><button class="chart-toggle" data-table-toggle aria-expanded="${tableOpen}">${tableOpen?'↑ ย่อตาราง':'↓ แสดงตาราง'}</button><button class="chart-toggle primary" data-table-csv>↓ ส่งออก CSV</button></div></div><div class="table-wrap"><table><thead><tr><th>ปี</th><th>รายได้</th><th>ค่าใช้จ่ายรวม</th><th>สุทธิ</th><th>สะสมปกติ</th><th>สะสมคิดลด</th></tr></thead><tbody>${result.cashflows.map(v=>{const simple=result.payback!=null&&Math.ceil(result.payback)===v.year,discount=result.discounted_payback!=null&&Math.ceil(result.discounted_payback)===v.year;const sg=(x,why='')=>`<td class="signed ${x<0?'neg':x>0?'pos':''}"${why?` title="${why}"`:''}>${x>0?'+':''}${fmt(x)}</td>`;return `<tr class="${simple?'simple-row':''} ${discount?'discount-row':''}"><td>${v.year}${simple?'<span class="table-badge payback-simple">● คืนทุน (ปกติ)</span>':''}${discount?'<span class="table-badge payback-discount">● คืนทุน (คิดลด)</span>':''}${v.replacement>0?`<span class="table-badge replace-badge" title="${explainYear(v).text}">เปลี่ยนอุปกรณ์ ${fmt(v.replacement)}</span>`:''}</td><td>${fmt(v.revenue)}</td><td>${fmt(v.om_cost+v.other_cost+v.replacement+(v.tax??0))}</td>${sg(v.net_cf,v.net_cf<0?explainYear(v).text:'')}${sg(v.cumulative)}${sg(v.discounted_cumulative)}</tr>`;}).join('')}</tbody></table></div><p class="graph-note">ทำเครื่องหมายปีแรกที่ยอดสะสมไม่ติดลบ · การคืนทุนจริงในแบบจำลองอาจเกิดระหว่างปี · มูลค่าซากรวมในกระแสเงินสดสุทธิปีสุดท้าย</p></section>`;
 if(page==='compare'){const all=allResults();html=`<p class="page-intro">เปรียบเทียบโครงการที่เลือกไว้ล่าสุดของแต่ละผลิตภัณฑ์ ชื่อลูกค้าระบุใต้ผลิตภัณฑ์แต่ละตัว</p><div class="compare-header">${all.map(pr=>`<article class="compare-item"><span>${pr.icon}</span><h3>${pr.name}</h3><div class="comparison-project-name">${esc(pr.projectName)}</div><p>${pr.result.scenario.project_life} ปี · คิดลด ${fmt(pr.result.scenario.discount_rate*100,1)}%</p><strong>${fmt(pr.result.scenario.initial_investment/1e6,2)} <small>ล้านบาท / เงินลงทุน</small></strong></article>`).join('')}</div><div class="chart-stack compare-chart-grid">${chartCard('npv')}${chartCard('recovery')}${chartCard('irr')}<section class="card compare-note"><div class="card-head"><div><h3>อ่านผลอย่างมีบริบท</h3><p>ต่างขนาด ต่างอายุ ต่างสมมติฐาน</p></div><span class="round-tag">✧</span></div><p style="font-size:12px;line-height:2;color:#a7bbd0">NPV แสดงมูลค่าปัจจุบันสุทธิ ส่วน IRR แสดงอัตราผลตอบแทน ควรพิจารณาคู่กับขนาดเงินลงทุน อายุโครงการ และจุดคืนทุน</p><p class="graph-note">ใช้สมมติฐานที่เทียบเคียงกันก่อนตัดสินใจเลือกโซลูชัน</p><div style="margin-top:25px"><button class="button primary" data-go-inputs>ปรับสมมติฐานโครงการ ↗</button></div></section></div><section class="card table-card"><div class="card-head"><h3>ตัวเลขเปรียบเทียบ</h3><span class="sample-tag">ข้อมูลสมมติ</span></div><div class="table-wrap"><table><thead><tr><th>ตัวชี้วัด</th>${all.map(pr=>`<th>${pr.name}</th>`).join('')}</tr></thead><tbody>${[['การตัดสินใจ',pr=>pr.result.decisionFinal.toUpperCase()+' · '+((pr.result.scenario.decision_override??'auto')==='auto'?'อัตโนมัติ':'เลือกเอง')],['NPV · ล้านบาท',pr=>fmt(pr.result.npv/1e6,2)],['IRR · %',pr=>pr.result.irr==null?'—':fmt(pr.result.irr*100,2)],['คืนทุนปกติ · ปี',pr=>yrs(pr.result.payback)],['คืนทุนคิดลด · ปี',pr=>yrs(pr.result.discounted_payback)]].map(([label,fn])=>`<tr><td>${label}</td>${all.map(pr=>`<td>${fn(pr)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
 if(page==='inputs')html=inputForm(s,result);
 $('#content').innerHTML=html;const tbl=$('#content .cashflow-table');if(tbl){tbl.querySelector('[data-table-toggle]').onclick=e=>{tableOpen=!tableOpen;tbl.classList.toggle('collapsed',!tableOpen);e.currentTarget.textContent=tableOpen?'↑ ย่อตาราง':'↓ แสดงตาราง';e.currentTarget.setAttribute('aria-expanded',tableOpen);};tbl.querySelector('[data-table-csv]').onclick=()=>$('#export').click();}
 document.querySelectorAll('[data-go-inputs]').forEach(b=>b.onclick=()=>navigate('inputs'));
 if(page==='inputs')bindInputs();bindCharts($('#content'));bindChartSizing();stagger($('#content'));requestAnimationFrame(fitFold);if(!welcome.active)countUp($('#content'),'.metric-value,.scenario-invest strong');
}
const fields=[['initial_investment','เงินลงทุนเริ่มต้น','บาท',1,0,1e9],['project_life','อายุโครงการ','ปี',1,1,40],['discount_rate','อัตราคิดลด','%',100,0,50],['revenue_y1','รายได้ / ผลประหยัดปีแรก','บาท/ปี',1,0,1e9],['revenue_growth','อัตราเติบโตของรายได้','%/ปี',100,-50,50],['revenue2_y1','รายได้ส่วนที่ 2 ปีแรก (ส่วนแบต)','บาท/ปี',1,0,1e9],['revenue2_growth','อัตราเติบโตรายได้ส่วนที่ 2','%/ปี',100,-50,50],['om_y1','ค่า O&M ปีแรก','บาท/ปี',1,0,1e8],['om_growth','อัตราเติบโตของ O&M','%/ปี',100,-50,50],['other_y1','ค่าใช้จ่ายอื่นปีแรก','บาท/ปี',1,0,1e8],['other_growth','อัตราเติบโตค่าใช้จ่ายอื่น','%/ปี',100,-50,50],['salvage_value','มูลค่าซาก (ติดลบ = ค่ารื้อถอน)','บาท',1,-1e9,1e9],['replacement_cost','ค่าเปลี่ยนอุปกรณ์','บาท',1,0,1e9],['replacement_year','ปีที่เปลี่ยนอุปกรณ์ (0 = ไม่มี)','ปี',1,0,40],['peak_rate','ค่าไฟช่วง Peak','บาท/kWh',1,0,100],['offpeak_rate','ค่าไฟช่วง Off-peak','บาท/kWh',1,0,100],['peak_energy_kwh_day','พลังงานย้ายช่วงต่อวัน','kWh',1,0,1e6],['energy_y1_kwh','พลังงานต่อปี (ไฟที่ลูกค้าใช้ได้)','kWh/ปี',1,0,1e9],['customer_saving_y1','ผลประหยัดของลูกค้าปีแรก (0 = คำนวณเอง)','บาท/ปี',1,0,1e9],['growth_switch_year','ปีที่เปลี่ยนอัตราเติบโต (0 = ไม่เปลี่ยน)','ปี',1,0,40,1],['revenue_growth_late','อัตราเติบโตของรายได้ หลังปีนั้น','%/ปี',100,-50,50,1],['revenue2_growth_late','อัตราเติบโตรายได้ส่วนที่ 2 หลังปีนั้น','%/ปี',100,-50,50,1],['revenue2_reset_every','รายได้ส่วนที่ 2 กลับเป็นของใหม่ทุก (ปี)','ปี',1,0,40,1],['revenue2_degradation','อัตราเสื่อมของรายได้ส่วนที่ 2','%/ปี',100,0,50,1],['replacement2_cost','ค่าเปลี่ยนอุปกรณ์รายการที่ 2','บาท',1,0,1e9,1],['replacement2_year','ปีที่เปลี่ยนรายการที่ 2 (0 = ไม่มี)','ปี',1,0,40,1],['replacement2_every','เปลี่ยนรายการที่ 2 ซ้ำทุก (ปี)','ปี',1,0,40,1],['tax_rate','อัตราภาษีเงินได้','%',100,0,50,1],['debt_share','สัดส่วนเงินกู้','%',100,0,100,1],['debt_rate','ดอกเบี้ยเงินกู้','%/ปี',100,0,30,1],['debt_years','ระยะผ่อนเงินกู้','ปี',1,0,40,1]];
const INT_FIELDS=new Set(['project_life','replacement_year','growth_switch_year','revenue2_reset_every','replacement2_year','replacement2_every','debt_years']);
const fieldShown=f=>(selected!=='solar'||!['offpeak_rate','peak_energy_kwh_day','customer_saving_y1'].includes(f[0]))&&(selected==='hybrid'||!['revenue2_y1','revenue2_growth','revenue2_growth_late','revenue2_reset_every','revenue2_degradation'].includes(f[0]));
const fieldHtml=([k,label,unit,m,min,max])=>`<label class="field">${label}<span class="input-wrap"><input aria-label="${label}" data-field="${k}" type="number" value="${Number(((data[selected][k]??0)*m).toFixed(8))}" min="${min}" max="${max}" step="${INT_FIELDS.has(k)?'1':'any'}"><span>${unit}</span></span></label>`;
const modeSwitch=mode=>`<div class="mode-switch" role="tablist" aria-label="วิธีกรอกข้อมูล"><i class="mode-pill" aria-hidden="true"></i><button data-input-mode="direct" class="${mode==='raw'?'':'active'}">กรอกเพื่อดูผลลัพธ์เอง</button><button data-input-mode="raw" class="${mode==='raw'?'active':''}">กรอกเพื่อให้ระบบคำนวณ</button></div>`;
const rawWait='<p class="raw-wait">ผลลัพธ์จะแสดงเมื่อกรอกครบทุกช่องที่ขึ้น ⚠ · ระหว่างนี้หน้าอื่นยังใช้ตัวเลขชุดเดิม</p>';
function inputForm(s,result){if(s.input_mode==='raw')return modeSwitch('raw')+rawFormHtml(selected,s,`${p().name} · ${esc(current()?.name??'')}`)+`<div class="live-results" id="live-results">${rawComplete(selected,s)?metricCards(result):rawWait}</div>`;return modeSwitch('direct')+`<section class="card input-card"><h3>${p().name} · ${esc(current()?.name??'')}</h3><p>ทดลองปรับตัวเลข ผลลัพธ์จะอัปเดตโดยไม่แตะข้อมูลจริง</p><div class="form-grid">${fields.filter(f=>fieldShown(f)&&!f[6]).map(fieldHtml).join('')}</div><details class="more-fields"><summary>ตัวเลือกเพิ่มเติม: อัตราเติบโตช่วงหลัง · เปลี่ยนอุปกรณ์รายการที่ 2 · ภาษี · เงินกู้</summary><div class="form-grid">${fields.filter(f=>fieldShown(f)&&f[6]).map(fieldHtml).join('')}</div></details><p id="input-error" class="error" role="status"></p><div class="form-actions"><button class="button primary" id="apply">ดูภาพการลงทุน ↗</button><p>อัตราเติบโตใส่ค่าติดลบได้ (เช่น แผงหรือแบตเสื่อม)<br>เก็บค่าแยกตามโครงการ ในเบราว์เซอร์นี้</p></div></section><div class="live-results" id="live-results">${metricCards(result)}</div>`;}
function bindInputs(){$('#content').querySelectorAll('[data-input-mode]').forEach(b=>b.onclick=()=>{const mode=b.dataset.inputMode,cur=data[selected];if((cur.input_mode==='raw')===(mode==='raw'))return;data[selected]={...cur,input_mode:mode,raw:cur.raw??defaultRaw()};modeJustSwitched=true;render();});placeModePill(modeJustSwitched);modeJustSwitched=false;liveTargets=$('#live-results .metric-value')?liveNums(metricCards(r())):null;if(document.fonts&&document.fonts.status!=='loaded')document.fonts.ready.then(()=>placeModePill(false));if(data[selected].input_mode==='raw'){bindRaw($('#content'),{product:selected,get:()=>data[selected],set:v=>{data[selected]=v;},rerender:()=>render(),onUpdate:complete=>{setLive(complete?metricCards(r()):rawWait);context();}});return;}const inputs=[...$('#content').querySelectorAll('[data-field]')];inputs.forEach(input=>input.oninput=()=>{const draft={...data[selected]};let error='';for(const el of inputs){const [k,label,unit,m,min,max]=fields.find(f=>f[0]===el.dataset.field),val=Number(el.value);if(el.value===''||!Number.isFinite(val)||val<min||val>max||(INT_FIELDS.has(k)&&!Number.isInteger(val))){error=`กรุณากรอก ${label} ระหว่าง ${min}–${max}`;break;}draft[k]=val/m;}if(!error&&draft.replacement_year>draft.project_life)error='ปีที่เปลี่ยนอุปกรณ์ต้องไม่เกินอายุโครงการ';if(!error&&(draft.replacement2_year??0)>draft.project_life)error='ปีที่เปลี่ยนรายการที่ 2 ต้องไม่เกินอายุโครงการ';$('#input-error').textContent=error;$('#apply').disabled=!!error;$('#live-results').hidden=!!error;$('#decision-panel').querySelectorAll('button').forEach(b=>b.disabled=!!error);if(!error){data[selected]=draft;setLive(metricCards(r()));context();}});$('#apply').onclick=()=>navigate('overview');}
